                                                                                                                                                              export type FeaturedCollection = {
                                                                                                                                                                id: string
                                                                                                                                                                  title: string
                                                                                                                                                                    description: string | null
                                                                                                                                                                      cover_image_url: string | null
                                                                                                                                                                        slug: string
                                                                                                                                                                          piece_count: number
                                                                                                                                                                            artist: {
                                                                                                                                                                                stage_name: string | null
                                                                                                                                                                                    username: string | null
                                                                                                                                                                                        avatar_url: string | null
                                                                                                                                                                                          } | null
                                                                                                                                                                                          }

                                                                                                                                                                                          async function getFeaturedCollections(): Promise<FeaturedCollection[]> {
                                                                                                                                                                                            try {
                                                                                                                                                                                                const admin = createAdminClient()

                                                                                                                                                                                                    const { data: setting } = await admin
                                                                                                                                                                                                          .from('platform_settings')
                                                                                                                                                                                                                .select('value')
                                                                                                                                                                                                                      .eq('key', 'featured_collection_id')
                                                                                                                                                                                                                            .single()
                                                                                                                                                                                                                                const pinnedId: string | null =
                                                                                                                                                                                                                                      setting?.value ? String(setting.value).replace(/"/g, '') : null

                                                                                                                                                                                                                                          // Fetch up to 5 active collections with cover images
                                                                                                                                                                                                                                              const { data: collections } = await admin
                                                                                                                                                                                                                                                    .from('collections')
                                                                                                                                                                                                                                                          .select('id, title, description, cover_image_url, slug, piece_count, artist_id')
                                                                                                                                                                                                                                                                .eq('status', 'active')
                                                                                                                                                                                                                                                                      .not('cover_image_url', 'is', null)
                                                                                                                                                                                                                                                                            .gt('piece_count', 0)
                                                                                                                                                                                                                                                                                  .order('created_at', { ascending: false })
                                                                                                                                                                                                                                                                                        .limit(5)

                                                                                                                                                                                                                                                                                            if (!collections?.length) return []

                                                                                                                                                                                                                                                                                                // Batch-fetch artist profiles and usernames
                                                                                                                                                                                                                                                                                                    const artistIds = [...new Set(collections.map((c) => c.artist_id))]
                                                                                                                                                                                                                                                                                                        const { data: artistProfiles } = await admin
                                                                                                                                                                                                                                                                                                              .from('artist_profiles')
                                                                                                                                                                                                                                                                                                                    .select('id, stage_name, avatar_url, user_id')
                                                                                                                                                                                                                                                                                                                          .in('id', artistIds)

                                                                                                                                                                                                                                                                                                                              const userIds = [...new Set((artistProfiles ?? []).map((ap) => ap.user_id).filter(Boolean))]
                                                                                                                                                                                                                                                                                                                                  const { data: profiles } = userIds.length
                                                                                                                                                                                                                                                                                                                                        ? await admin.from('profiles').select('id, username').in('id', userIds)
                                                                                                                                                                                                                                                                                                                                              : { data: [] as { id: string; username: string | null }[] }

                                                                                                                                                                                                                                                                                                                                                  const artistMap = new Map((artistProfiles ?? []).map((ap) => [ap.id, ap]))
                                                                                                                                                                                                                                                                                                                                                      const profileMap = new Map((profiles ?? []).map((p) => [p.id, p]))

                                                                                                                                                                                                                                                                                                                                                          const results: FeaturedCollection[] = collections.map((c) => {
                                                                                                                                                                                                                                                                                                                                                                const ap = artistMap.get(c.artist_id)
                                                                                                                                                                                                                                                                                                                                                                      const username = ap?.user_id ? (profileMap.get(ap.user_id)?.username ?? null) : null
                                                                                                                                                                                                                                                                                                                                                                            return {
                                                                                                                                                                                                                                                                                                                                                                                    id: c.id,
                                                                                                                                                                                                                                                                                                                                                                                            title: c.title,
                                                                                                                                                                                                                                                                                                                                                                                                    description: c.description,
                                                                                                                                                                                                                                                                                                                                                                                                            cover_image_url: c.cover_image_url,
                                                                                                                                                                                                                                                                                                                                                                                                                    slug: c.slug,
                                                                                                                                                                                                                                                                                                                                                                                                                            piece_count: c.piece_count,
                                                                                                                                                                                                                                                                                                                                                                                                                                    artist: ap ? { stage_name: ap.stage_name, avatar_url: ap.avatar_url, username } : null,
                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                              })

                                                                                                                                                                                                                                                                                                                                                                                                                                                  // Put pinned collection first
                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (pinnedId) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                            const pinnedIdx = results.findIndex((r) => r.id === pinnedId)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (pinnedIdx > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const [pinned] = results.splice(pinnedIdx, 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  results.unshift(pinned)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return results
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return []
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

